import 'dart:io';
import 'package:audioplayers/audioplayers.dart';

enum AlertKind { call, videoCall, message, file }

/// Original app-specific PCM melodies, generated by tool/generate_assets.py.
/// Playback errors cannot break chat, transfer or WebRTC signaling.
class Alerts {
  AudioPlayer? _ringer;
  AudioPlayer? _effect;
  int _ringGeneration = 0;
  bool enabled = true;
  bool useAppSounds = true;
  final Map<AlertKind, String> customSounds = {};
  Source _source(AlertKind kind) {
    final path = customSounds[kind];
    if (!useAppSounds && path != null && path.isNotEmpty && File(path).existsSync()) {
      return DeviceFileSource(path);
    }
    return AssetSource(_asset(kind));
  }


  String _asset(AlertKind kind) => switch (kind) {
    AlertKind.call => 'sounds/call.wav',
    AlertKind.videoCall => 'sounds/video_call.wav',
    AlertKind.message => 'sounds/message.wav',
    AlertKind.file => 'sounds/file.wav',
  };

  Future<void> ring(AlertKind kind) async {
    if (!enabled) return;
    final generation = ++_ringGeneration;
    final previous = _ringer;
    _ringer = null;
    if (previous != null) {
      try { await previous.stop(); await previous.dispose(); } catch (_) {}
    }
    if (generation != _ringGeneration || !enabled) return;
    final player = AudioPlayer();
    _ringer = player;
    try {
      await player.setReleaseMode(ReleaseMode.loop);
      if (generation != _ringGeneration || !enabled) return;
      await player.play(_source(kind));
      if (generation != _ringGeneration || !enabled) await stopRing();
    } catch (_) {
      if (identical(_ringer, player)) _ringer = null;
      try { await player.dispose(); } catch (_) {}
    }
  }

  Future<void> stopRing() async {
    ++_ringGeneration;
    final player = _ringer;
    _ringer = null;
    if (player == null) return;
    try { await player.stop(); await player.dispose(); } catch (_) {}
  }

  Future<void> notify(AlertKind kind) async {
    if (!enabled) return;
    try {
      final effect = _effect ??= AudioPlayer();
      await effect.stop();
      await effect.play(_source(kind));
    } catch (_) {}
  }

  Future<void> dispose() async {
    await stopRing();
    await _effect?.dispose();
    _effect = null;
  }
}